import torch
import torch.nn as nn

class Model(nn.Module):
    """
    Simple model that finds the index of the minimum value along a specified dimension.
    """
    def __init__(self, dim: int):
        """
        Initializes the model with the dimension to perform argmin on.

        Args:
            dim (int): Dimension along which to find the minimum value.
        """
        super(Model, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Finds the index of the minimum value along the specified dimension.

        Args:
            x (torch.Tensor): Input tensor.

        Returns:
            torch.Tensor: Tensor containing the indices of the minimum values along the specified dimension.
        """
        # Custom CUDA operator for argmin along a specific dimension
        def custom_argmin_along_dim(x, dim):
            # Get the shape of the input tensor
            size = x.size(0)

            # Initialize output tensor with zeros
            out = torch.zeros_like(x)

            # Calculate number of blocks and threads per block
            num_blocks = (size + dim - 1) // dim
            block_size = dim

            # Perform argmin operation using custom CUDA kernel
            elementwise_add_kernel<<<num_blocks, block_size>>>(x.data_ptr(), x.data_ptr(), out.data_ptr(), size)

            return out

        # Replace torch.argmin with our custom implementation
        self.forward = nn.ModuleDict({
            'forward': lambda self, x: custom_argmin_along_dim(x, self.dim)(x))
        })

        return Model(self.dim)

